/**
 * Runtime configuration injected by /config.js before the app module runs.
 * The file is generated by the container entrypoint; `public/config.js` is the
 * development default. Missing or malformed configuration disables demo hints
 * rather than breaking the app.
 */

export interface RuntimeConfig {
  demoMode: boolean;
  demoUsername?: string;
  demoPassword?: string;
  demoOtp?: string;
}

declare global {
  interface Window {
    __SME_CONFIG__?: unknown;
  }
}

const FALLBACK: RuntimeConfig = { demoMode: false };

function nonEmptyString(value: unknown): string | undefined {
  return typeof value === "string" && value.length > 0 ? value : undefined;
}

export function readConfig(raw: unknown = window.__SME_CONFIG__): RuntimeConfig {
  if (typeof raw !== "object" || raw === null) {
    return FALLBACK;
  }

  const candidate = raw as Record<string, unknown>;
  if (candidate.demoMode !== true) {
    return FALLBACK;
  }

  const config: RuntimeConfig = { demoMode: true };
  const username = nonEmptyString(candidate.demoUsername);
  const password = nonEmptyString(candidate.demoPassword);
  const otp = nonEmptyString(candidate.demoOtp);
  if (username) config.demoUsername = username;
  if (password) config.demoPassword = password;
  if (otp) config.demoOtp = otp;
  return config;
}

export function getConfig(): RuntimeConfig {
  return readConfig();
}
